import { useRef, useCallback, useEffect } from "react";
import { redrawAll } from "../annotate/strokes";

// ── Page render cache + prefetch ──────────────────────────────────────────
// Pure extraction from the old monolithic ScoreViewer.jsx — no behavior change.
// Renders a PDF page into an offscreen canvas (cached by page+zoom), then
// swaps it atomically into the visible canvas pair (no blank frame), and
// opportunistically prefetches neighboring pages once the current one paints.
export function useRenderCache({ pdfDoc, docId, zoom, strokesRef }) {
  const pageCacheRef     = useRef(new Map()); // pageNum → { canvas, zoom }
  const prefetchTasksRef = useRef(new Map()); // pageNum → in-progress render task

  const clearPageCache = useCallback(() => {
    prefetchTasksRef.current.forEach(t => t.cancel?.());
    prefetchTasksRef.current.clear();
    pageCacheRef.current.clear();
  }, []);

  // Pre-render a page into the cache without touching the visible canvas.
  // Cache entries carry the zoom they were rendered at, so a stale entry
  // from before a zoom change (e.g. switching page layout) is never mistaken
  // for a fresh one — relying on effect ordering to clear it in time is not
  // safe (a render effect can run, and read the cache, before the "clear
  // cache on zoom change" effect does in the same commit).
  const prefetchPage = useCallback((doc, pNum, z) => {
    if (!doc || pNum < 1 || pNum > doc.numPages) return;
    if (pageCacheRef.current.get(pNum)?.zoom === z) return;
    if (prefetchTasksRef.current.has(pNum)) return;

    doc.getPage(pNum).then(page => {
      if (pageCacheRef.current.get(pNum)?.zoom === z) { page.cleanup(); return; }
      const vp = page.getViewport({ scale: z });
      const offscreen = document.createElement("canvas");
      offscreen.width = vp.width;
      offscreen.height = vp.height;
      const task = page.render({ canvasContext: offscreen.getContext("2d"), viewport: vp });
      prefetchTasksRef.current.set(pNum, task);
      task.promise
        .then(() => {
          page.cleanup();
          prefetchTasksRef.current.delete(pNum);
          pageCacheRef.current.set(pNum, { canvas: offscreen, zoom: z });
        })
        .catch(() => { prefetchTasksRef.current.delete(pNum); });
    }).catch(() => {});
  }, []);

  // Render a single page into a given canvas pair. Uses pre-rendered cache
  // when available (instant page turn), otherwise renders offscreen first
  // then swaps atomically. Shared by every pane in every layout mode.
  const renderPageInto = useCallback((pNum, cvs, ann, taskRef, pageRef, onDone) => {
    if (!pdfDoc || !cvs || !ann || pNum < 1 || pNum > pdfDoc.numPages) return () => {};

    let cancelled = false;

    taskRef.current?.cancel();
    taskRef.current = null;
    pageRef.current?.cleanup();
    pageRef.current = null;

    const applyCanvas = (offscreen) => {
      if (cancelled) return;
      cvs.width  = ann.width  = offscreen.width;
      cvs.height = ann.height = offscreen.height;
      cvs.getContext("2d").drawImage(offscreen, 0, 0);
      // Strokes/stamps are stored zoom-independent — redraw at the CURRENT
      // zoom every time, not just whatever zoom they were drawn at.
      redrawAll(ann, strokesRef.current[`${docId}-${pNum}`] || [], null, zoom);
      onDone?.();
      // Prefetch neighbors now that current page is painted
      prefetchPage(pdfDoc, pNum + 1, zoom);
      prefetchPage(pdfDoc, pNum - 1, zoom);
    };

    // Cache hit (same page AND same zoom) → instant display, no async wait
    const cached = pageCacheRef.current.get(pNum);
    if (cached?.zoom === zoom) {
      applyCanvas(cached.canvas);
      return () => { cancelled = true; };
    }

    pdfDoc.getPage(pNum).then(page => {
      if (cancelled) { page.cleanup(); return; }
      pageRef.current = page;
      const vp = page.getViewport({ scale: zoom });
      const offscreen = document.createElement("canvas");
      offscreen.width  = vp.width;
      offscreen.height = vp.height;
      const task = page.render({ canvasContext: offscreen.getContext("2d"), viewport: vp });
      taskRef.current = task;
      task.promise
        .then(() => {
          page.cleanup();
          pageRef.current = null;
          pageCacheRef.current.set(pNum, { canvas: offscreen, zoom });
          applyCanvas(offscreen);
        })
        .catch(() => {});
    }).catch(() => {});

    return () => { cancelled = true; };
  }, [pdfDoc, docId, zoom, prefetchPage]); // strokes intentionally excluded — annotation changes must not trigger a PDF re-render

  // Clear cache when zoom or document changes (cached canvases are at the old scale)
  useEffect(() => { clearPageCache(); }, [zoom, docId, clearPageCache]);

  return { renderPageInto, clearPageCache, pageCacheRef };
}
