// ── Musical stamps: hairpins, dynamics, articulations, fingering, text ────
// Drawn procedurally on canvas — no image assets needed. Each stamp item:
//   { type: "stamp", kind, x, y, w, h, text?, thickness?, fontSize? }
// (x,y,w,h) is the stamp's bounding box in ZOOM-INDEPENDENT page coordinates
// (the page's own scale=1 space) — same space freehand strokes already use,
// so stamps live in the SAME per-page `strokes[key]` array and are fully
// transparent to undo/redo. `drawStamp`'s `scale` (always the current zoom)
// is applied only at draw time, so a stamp stays correctly anchored to the
// page at any zoom instead of only looking right at the zoom it was placed at.

export const STAMP_KINDS = [
  { id: "hairpin-cresc", label: "Crescendo" },
  { id: "hairpin-dim",   label: "Diminuendo" },
  { id: "dynamic",       label: "Dinámica" },
  { id: "accent",        label: "Acento" },
  { id: "tenuto",        label: "Tenuto" },
  { id: "marcato",       label: "Marcato" },
  { id: "staccato",      label: "Staccato" },
  { id: "fermata",       label: "Calderón" },
  { id: "fingering",     label: "Dedo" },
  { id: "text",          label: "Texto" },
];

export const DYNAMIC_TEXTS   = ["pp", "p", "mp", "mf", "f", "ff", "sfz"];
export const FINGERING_TEXTS = ["1", "2", "3", "4", "5"];

// Kinds resizable from BOTH ends (length-oriented marks) vs. simple
// corner-resize (everything else, including text where h also sets font size).
const END_RESIZABLE = new Set(["hairpin-cresc", "hairpin-dim", "tenuto"]);
export function isEndResizable(kind) { return END_RESIZABLE.has(kind); }

function drawHairpin(ctx, item, opening) {
  const { x, y, w, h, color = "#1a1a1a", thickness } = item;
  const midY = y + h / 2;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth   = thickness || Math.max(1.5, h * 0.08);
  ctx.lineCap     = "round";
  ctx.beginPath();
  if (opening) {
    // crescendo: narrow on the left, wide on the right  <
    ctx.moveTo(x, midY);
    ctx.lineTo(x + w, y);
    ctx.moveTo(x, midY);
    ctx.lineTo(x + w, y + h);
  } else {
    // diminuendo: wide on the left, narrow on the right  >
    ctx.moveTo(x, y);
    ctx.lineTo(x + w, midY);
    ctx.moveTo(x, y + h);
    ctx.lineTo(x + w, midY);
  }
  ctx.stroke();
  ctx.restore();
}

function drawText(ctx, item, { italic = true } = {}) {
  const { x, y, w, h, text = "", color = "#1a1a1a", fontSize } = item;
  ctx.save();
  ctx.fillStyle = color;
  const size = fontSize || Math.max(12, h * 0.8);
  ctx.font = `${italic ? "italic " : ""}700 ${size}px ${italic ? "'Playfair Display', Georgia, serif" : "system-ui, sans-serif"}`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, x + w / 2, y + h / 2);
  ctx.restore();
}

// ── Articulation marks ─────────────────────────────────────────────────
function drawAccent(ctx, item) {
  const { x, y, w, h, color = "#1a1a1a", thickness } = item;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = thickness || Math.max(1.5, h * 0.1);
  ctx.lineCap = "round"; ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(x, y); ctx.lineTo(x + w, y + h / 2); ctx.lineTo(x, y + h);
  ctx.stroke();
  ctx.restore();
}

function drawTenuto(ctx, item) {
  const { x, y, w, h, color = "#1a1a1a", thickness } = item;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = thickness || Math.max(2, h * 0.25);
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(x, y + h / 2); ctx.lineTo(x + w, y + h / 2);
  ctx.stroke();
  ctx.restore();
}

function drawMarcato(ctx, item) {
  const { x, y, w, h, color = "#1a1a1a", thickness } = item;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = thickness || Math.max(1.5, h * 0.12);
  ctx.lineCap = "round"; ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(x, y + h); ctx.lineTo(x + w / 2, y); ctx.lineTo(x + w, y + h);
  ctx.stroke();
  ctx.restore();
}

function drawStaccato(ctx, item) {
  const { x, y, w, h, color = "#1a1a1a" } = item;
  ctx.save();
  ctx.fillStyle = color;
  const r = Math.min(w, h) / 2;
  ctx.beginPath();
  ctx.arc(x + w / 2, y + h / 2, Math.max(2, r), 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawFermata(ctx, item) {
  const { x, y, w, h, color = "#1a1a1a", thickness } = item;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = thickness || Math.max(1.5, h * 0.08);
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h, w / 2, h, 0, Math.PI, 0, true);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(x + w / 2, y + h * 0.62, Math.max(1.8, h * 0.12), 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

export function drawStamp(ctx, item, selected, scale = 1) {
  const s = scale === 1 ? item : { ...item, x: item.x * scale, y: item.y * scale, w: item.w * scale, h: item.h * scale, thickness: item.thickness ? item.thickness * scale : undefined, fontSize: item.fontSize ? item.fontSize * scale : undefined };
  switch (item.kind) {
    case "hairpin-cresc": drawHairpin(ctx, s, true); break;
    case "hairpin-dim":   drawHairpin(ctx, s, false); break;
    case "dynamic":       drawText(ctx, s, { italic: true }); break;
    case "fingering":     drawText(ctx, s, { italic: false }); break;
    case "text":          drawText(ctx, s, { italic: false }); break;
    case "accent":        drawAccent(ctx, s); break;
    case "tenuto":        drawTenuto(ctx, s); break;
    case "marcato":       drawMarcato(ctx, s); break;
    case "staccato":      drawStaccato(ctx, s); break;
    case "fermata":       drawFermata(ctx, s); break;
    default: break;
  }
  if (selected) {
    ctx.save();
    ctx.strokeStyle = "#2e74b5";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 3]);
    const pad = 3 * scale;
    ctx.strokeRect(s.x - pad, s.y - pad, s.w + pad * 2, s.h + pad * 2);
    ctx.restore();
  }
}

// Default size/text for a newly placed stamp of a given kind, centered on (x, y).
export function makeStamp(kind, x, y, extra = {}) {
  const base = { id: `stamp-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, type: "stamp", kind, color: "#1a1a1a" };
  if (kind === "hairpin-cresc" || kind === "hairpin-dim") {
    return { ...base, x: x - 40, y: y - 10, w: 80, h: 20, ...extra };
  }
  if (kind === "tenuto") {
    return { ...base, x: x - 14, y: y - 4, w: 28, h: 8, ...extra };
  }
  if (kind === "accent" || kind === "marcato") {
    return { ...base, x: x - 10, y: y - 8, w: 20, h: 16, ...extra };
  }
  if (kind === "staccato") {
    return { ...base, x: x - 5, y: y - 5, w: 10, h: 10, ...extra };
  }
  if (kind === "fermata") {
    return { ...base, x: x - 14, y: y - 10, w: 28, h: 14, ...extra };
  }
  if (kind === "text") {
    return { ...base, x: x - 30, y: y - 12, w: 60, h: 24, text: extra.text || "", fontSize: 18, ...extra };
  }
  // dynamic / fingering
  return { ...base, x: x - 16, y: y - 14, w: 32, h: 28, text: extra.text || (kind === "dynamic" ? "mf" : "1"), ...extra };
}

// Hit test — is (px, py) inside this stamp's bounding box?
export function hitTestStamp(item, px, py) {
  return px >= item.x && px <= item.x + item.w && py >= item.y && py <= item.y + item.h;
}

// Corner resize-handle hit test (bottom-right handle, ~10 unit square)
export function hitTestResizeHandle(item, px, py) {
  const hx = item.x + item.w, hy = item.y + item.h;
  return Math.abs(px - hx) <= 10 && Math.abs(py - hy) <= 10;
}

// Left-edge handle — length-oriented marks (hairpins, tenuto) can also be
// stretched from their start, not just the end, so a crescendo's left tip
// can be repositioned without moving its right tip ("longitud... se dejan
// editar" from other apps' hairpin tools).
export function hitTestLeftHandle(item, px, py) {
  if (!isEndResizable(item.kind)) return false;
  const midY = item.y + item.h / 2;
  return Math.abs(px - item.x) <= 10 && Math.abs(py - midY) <= Math.max(10, item.h / 2 + 4);
}
