import * as pdfjsLib from "pdfjs-dist/legacy/build/pdf";

let wired = false;

// Worker served as a plain static file from public/pdf.worker.min.js (kept
// in sync by scripts/copy-pdf-worker.js on `npm install`) — not loaded via
// webpack's `new URL(..., import.meta.url)` asset pipeline. That approach
// (tried first) hit two different failures specifically on Safari/iOS:
// "Setting up fake worker failed: window.pdfjsWorker undefined" (pdf.js's
// real-vs-fake-worker auto-detection misfiring), and then, after forcing a
// real Worker explicitly, the worker simply never completed its handshake
// at all. A plain, unhashed static file with a stable URL and zero webpack
// transformation is the well-proven pattern for this exact class of bug.
export function getPdfjs() {
  if (!wired) {
    const workerHref = `${process.env.PUBLIC_URL || ""}/pdf.worker.min.js`;
    try {
      pdfjsLib.GlobalWorkerOptions.workerPort = new Worker(workerHref);
    } catch {
      // Extremely old/locked-down environments without Worker support at
      // all — fall back to pdf.js's own loading strategy rather than crash.
      pdfjsLib.GlobalWorkerOptions.workerSrc = workerHref;
    }
    wired = true;
  }
  return pdfjsLib;
}

// Wraps a promise so a stuck/never-resolving load (e.g. a worker that
// started but never completed its handshake) surfaces as an error after a
// reasonable wait instead of spinning forever with no feedback.
export function withTimeout(promise, ms, message) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(message)), ms);
    promise.then(
      (v) => { clearTimeout(t); resolve(v); },
      (e) => { clearTimeout(t); reject(e); }
    );
  });
}
